-- Comercial La Estrella | Migracion Oracle -> SQL Server 2022
-- Datos historicos: no instalar triggers de venta antes de importar.
-- Ejecutar con sqlcmd -b. Script reejecutable: no duplica las tablas pobladas.
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF DB_ID(N'ComercialLaEstrella') IS NULL CREATE DATABASE [ComercialLaEstrella];
GO
USE [ComercialLaEstrella];
GO
-- TABLAS
IF OBJECT_ID(N'dbo.PAIS', N'U') IS NULL
BEGIN
  CREATE TABLE [dbo].[PAIS] (
    [ID_PA] INT NOT NULL,
    [NOMBRE_PA] NVARCHAR(50) NOT NULL,
    CONSTRAINT [PAIS_PK] PRIMARY KEY ([ID_PA])
  );
END;
GO
