-- VERIFICACION DE MIGRACION
USE [ComercialLaEstrella];
GO
SELECT COUNT(*) AS TotalTablas FROM sys.tables WHERE schema_id = SCHEMA_ID(N'dbo');
SELECT COUNT(*) AS TotalClavesForaneas FROM sys.foreign_keys WHERE is_disabled = 0 AND is_not_trusted = 0;
SELECT nombre_tabla, registros_esperados, registros_actuales, CASE WHEN registros_esperados = registros_actuales THEN 'OK' ELSE 'REVISAR' END AS estado FROM (
SELECT N'PAIS' AS nombre_tabla, 3 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[PAIS]) AS registros_actuales UNION ALL
SELECT N'DEPARTAMENTO' AS nombre_tabla, 32 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[DEPARTAMENTO]) AS registros_actuales UNION ALL
SELECT N'MUNICIPIO' AS nombre_tabla, 80 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[MUNICIPIO]) AS registros_actuales UNION ALL
SELECT N'TIPO_TIENDA' AS nombre_tabla, 4 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[TIPO_TIENDA]) AS registros_actuales UNION ALL
SELECT N'TIENDA' AS nombre_tabla, 20 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[TIENDA]) AS registros_actuales UNION ALL
SELECT N'CARGO' AS nombre_tabla, 4 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[CARGO]) AS registros_actuales UNION ALL
SELECT N'CATEGORIA' AS nombre_tabla, 10 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[CATEGORIA]) AS registros_actuales UNION ALL
SELECT N'MARCA' AS nombre_tabla, 15 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[MARCA]) AS registros_actuales UNION ALL
SELECT N'TIPO_IDENTIFICACION' AS nombre_tabla, 3 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[TIPO_IDENTIFICACION]) AS registros_actuales UNION ALL
SELECT N'ESTADO_VENTA' AS nombre_tabla, 3 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[ESTADO_VENTA]) AS registros_actuales UNION ALL
SELECT N'METODO_PAGO' AS nombre_tabla, 4 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[METODO_PAGO]) AS registros_actuales UNION ALL
SELECT N'PERSONA' AS nombre_tabla, 388 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[PERSONA]) AS registros_actuales UNION ALL
SELECT N'CLIENTE' AS nombre_tabla, 300 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[CLIENTE]) AS registros_actuales UNION ALL
SELECT N'PRODUCTO' AS nombre_tabla, 114 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[PRODUCTO]) AS registros_actuales UNION ALL
SELECT N'EMPLEADO' AS nombre_tabla, 88 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[EMPLEADO]) AS registros_actuales UNION ALL
SELECT N'CATALOGO_PRODUCTO' AS nombre_tabla, 1424 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[CATALOGO_PRODUCTO]) AS registros_actuales UNION ALL
SELECT N'VENTA' AS nombre_tabla, 1500 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[VENTA]) AS registros_actuales UNION ALL
SELECT N'DESGLOSE_VENTA' AS nombre_tabla, 3687 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[DESGLOSE_VENTA]) AS registros_actuales UNION ALL
SELECT N'PAGO' AS nombre_tabla, 1389 AS registros_esperados, (SELECT COUNT(*) FROM [dbo].[PAGO]) AS registros_actuales) AS auditoria ORDER BY nombre_tabla;
GO
